const scene=document.getElementById('scene'), flow=document.getElementById('flow'), verb=document.getElementById('verb'), channel=document.getElementById('channel'), labelcontent=document.getElementById('labelcontent');
const data=[
 ['Ontwerpen','websites','data:image/webp;base64,',['#173c31','#4c7663'],0],
 ['Schrijven','copy','data:image/webp;base64,',['#25193c','#832558'],1],
 ['Optimaliseren','SEO','data:image/webp;base64,',['#251819','#992d3c'],2],
 ['Bouwen','webshops','data:image/webp;base64,',['#38231c','#994b31'],3],
 ['Automatiseren','processen','data:image/webp;base64,',['#153b38','#52756c'],0],
 ['Koppelen','systemen','data:image/webp;base64,',['#4b241c','#9b3037'],1],
 ['Ontwikkelen','dashboards','data:image/webp;base64,',['#4c2819','#9f4d2f'],2],
 ['Plannen','boekingen','data:image/webp;base64,',['#30291f','#775d3d'],3],
 ['Vormgeven','branding','data:image/webp;base64,',['#271c3b','#6f3c69'],0],
 ['Onderhouden','websites','data:image/webp;base64,',['#2b271e','#6a5136'],1]
];
const paths=[
 'M22 22 H43 C40 12 45 6 51 6 C58 6 62 12 59 22 H78 V43 C88 40 94 45 94 51 C94 58 88 62 78 59 V78 H58 C61 88 56 94 50 94 C43 94 39 88 42 78 H22 V58 C12 61 6 56 6 50 C6 43 12 39 22 42 Z',
 'M22 22 H42 C39 12 44 6 50 6 C57 6 61 12 58 22 H78 V42 C68 39 62 44 62 50 C62 57 68 61 78 58 V78 H58 C61 88 56 94 50 94 C43 94 39 88 42 78 H22 V58 C32 61 38 56 38 50 C38 43 32 39 22 42 Z',
 'M22 22 H43 C40 32 45 38 51 38 C58 38 62 32 59 22 H78 V42 C88 39 94 44 94 50 C94 57 88 61 78 58 V78 H58 C61 68 56 62 50 62 C43 62 39 68 42 78 H22 V58 C12 61 6 56 6 50 C6 43 12 39 22 42 Z',
 'M22 22 H42 C39 12 44 6 50 6 C57 6 61 12 58 22 H78 V42 C68 39 62 44 62 50 C62 57 68 61 78 58 V78 H58 C61 68 56 62 50 62 C43 62 39 68 42 78 H22 V58 C12 61 6 56 6 50 C6 43 12 39 22 42 Z'
];
function mix(hex,amt){const c=hex.replace('#','');const n=parseInt(c,16);let r=(n>>16)&255,g=(n>>8)&255,b=n&255;r=Math.round(r+(255-r)*amt);g=Math.round(g+(255-g)*amt);b=Math.round(b+(255-b)*amt);return `#${r.toString(16).padStart(2,'0')}${g.toString(16).padStart(2,'0')}${b.toString(16).padStart(2,'0')}`}
function svgPiece(d,i){const g=`g${i}`;const lightA=mix(d[3][0],.42), lightB=mix(d[3][1],.24);return `<svg viewBox="0 0 100 100"><defs><linearGradient id="${g}" x1="10" y1="8" x2="92" y2="94"><stop stop-color="${lightA}"/><stop offset="1" stop-color="${lightB}"/></linearGradient><linearGradient id="s${i}" x1="16" y1="10" x2="82" y2="86"><stop stop-color="#fff" stop-opacity=".18"/><stop offset=".42" stop-color="#fff" stop-opacity=".06"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient></defs><path d="${paths[d[4]%paths.length]}" fill="url(#${g})"/><path d="${paths[d[4]%paths.length]}" fill="url(#s${i})"/></svg>`}
const units=data.map((d,i)=>{const el=document.createElement('div');el.className='unit';el.innerHTML=`<div class="bubble"><img src="${d[2]}" alt="${d[0]} ${d[1]}" loading="eager" decoding="async"></div><div class="piece">${svgPiece(d,i)}</div>`;flow.appendChild(el);return {el,b:el.querySelector('.bubble'),p:el.querySelector('.piece')}});
const N=data.length, MOVE=1180, HOLD=2000, CYCLE=MOVE+HOLD; let start=performance.now(); let lastLabel=0; let labelSwapToken=0;
function swapLabel(idx){
  if(idx===lastLabel)return;
  lastLabel=idx;
  const token=++labelSwapToken;
  const out=labelcontent.animate([
    {opacity:1,transform:'translate3d(0,0,0)',filter:'blur(0px)'},
    {opacity:0,transform:'translate3d(0,-7px,0)',filter:'blur(2.5px)'}
  ],{duration:160,easing:'cubic-bezier(.4,0,1,1)',fill:'forwards'});
  out.finished.then(()=>{
    if(token!==labelSwapToken)return;
    verb.textContent=data[idx][0];
    channel.textContent=data[idx][1];
    labelcontent.animate([
      {opacity:0,transform:'translate3d(0,8px,0)',filter:'blur(2.5px)'},
      {opacity:1,transform:'translate3d(0,0,0)',filter:'blur(0px)'}
    ],{duration:320,easing:'cubic-bezier(.16,1,.3,1)',fill:'forwards'});
  }).catch(()=>{});
}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const smooth=x=>{x=clamp(x,0,1);return x*x*(3-2*x)};
function cycDiff(i,base){let d=i-base;while(d>N/2)d-=N;while(d<-N/2)d+=N;return d}
function slotPos(slot,w,h){
 const mobile=w<850;
 const fx=mobile?w*.67:w*.71;
 const fy=mobile?h*.715:h*.50;
 const radius=mobile?Math.min(178,w*.455):282;
 const angleStep=mobile?.58:.445;
 const theta=slot*angleStep;
 const cx=fx-radius;
 return {x:cx+radius*Math.cos(theta),y:fy+radius*Math.sin(theta),fx,fy};
}
function frame(now){
 const r=scene.getBoundingClientRect(), w=r.width,h=r.height;
 const elapsed=now-start, base=Math.floor(elapsed/CYCLE), inCycle=elapsed-base*CYCLE;
 const phase=Math.min(inCycle/MOVE,1);
 const move=smooth(phase);
 const morphIn=smooth((phase-.28)/.58);
 const morphOut=1-smooth((phase-.18)/.58);
 const labelIdx=((base+(phase>=.96?1:0))%N+N)%N;
 if(labelIdx!==lastLabel)swapLabel(labelIdx)
 for(let i=0;i<N;i++){
   const d=cycDiff(i,base%N);
   let slot=-d+move;
   let morph=0;
   if(d===0)morph=morphOut; else if(d===1)morph=morphIn;
   const pos=slotPos(slot,w,h);
   const magnet=Math.pow(morph,.62);
   const x=pos.x+(pos.fx-pos.x)*magnet;
   const y=pos.y+(pos.fy-pos.y)*magnet;
   const abs=Math.abs(slot);
   const visibility=clamp(1-(abs-3.15)/1.05,0,1);
   const bubbleScale=(.98*Math.exp(-.115*abs))*(1-.18*morph);
   const pieceScale=.86+.14*morph;
   const bubbleOpacity=(1-morph)*visibility;
   const pieceOpacity=morph*visibility;
   units[i].el.style.transform=`translate3d(${x}px,${y}px,0)`;
   units[i].el.style.opacity=visibility.toFixed(3);
   units[i].el.style.zIndex=String(10+Math.round(morph*30)+(4-Math.min(4,Math.round(abs))));
   units[i].b.style.opacity=bubbleOpacity.toFixed(3);
   units[i].b.style.transform=`translate(-50%,-50%) scale(${bubbleScale.toFixed(4)})`;
   units[i].p.style.opacity=pieceOpacity.toFixed(3);
   units[i].p.style.transform=`translate(-50%,-50%) scale(${pieceScale.toFixed(4)})`;
 }
 requestAnimationFrame(frame)
}
requestAnimationFrame(frame)
